function Panel(props:any){return <DraftProvider ui={nativeUi}><PanelContent {...props}/></DraftProvider>;}

export function apply(ctx:any){
  const api=new HumanClient(ctx);
  ctx.effect(()=>()=>api.dispose(),'Human native client model');
  ctx.inject(['dshImClient'],(scope:any)=>{api.im=scope.dshImClient;const was=api.im.settingsVisible();api.im.setSettingsVisible(false);scope.effect(()=>()=>{api.im?.setSettingsVisible(was);api.im=null;});});
  const register=(key:string,fn:()=>any)=>ctx.slots.inject(key,fn);
  register('sidebar.panellist',()=>ctx.slots.register({name:'sidebar.panellist',id:PANEL,order:11,label:'Human'},Icon));
  register('main',()=>{const one=ctx.slots.register({name:'main',key:PANEL,inject:()=>({api,initialView:'chat',hooks:{human:api}})},Panel),two=ctx.slots.register({name:'main',key:EVENTS,inject:()=>({api,initialView:'activity',hooks:{human:api}})},Panel),three=ctx.slots.register({name:'main',key:TIMELINE,inject:()=>({api,initialView:'brain',hooks:{human:api}})},Panel);if(new URLSearchParams(location.search).get('human')==='1')queueMicrotask(()=>ctx.layout.selectPanel(PANEL));return ()=>{three();two();one();};});
}


